 $by=[];$superseded=[];foreach($rows as $r)$by[(int)$r['id']]=$r;
 foreach($rows as $r){$v=decode($r['body_json']);$prev=(int)($v['previous_id']??0);if($prev&&isset($by[$prev])&&($r['status']??'')==='approved'&&($effectiveOn===null||$r['date_from']<=$effectiveOn))$superseded[$prev]=true;}
 $result=[];foreach($rows as $r){$id=(int)$r['id'];$root=$id;$seen=[];while(isset($by[$root])&&!isset($seen[$root])){$seen[$root]=true;$prev=(int)(decode($by[$root]['body_json'])['previous_id']??0);if(!$prev||!isset($by[$prev]))break;$root=$prev;}$result[$id]=['version_root32'=>$root,'version_current32'=>!isset($superseded[$id])];}return $result;
}
